import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"Configuration & state","description":"Mobile Inspector development documentation · Configuration & state","frontmatter":{"title":"Configuration & state","description":"Mobile Inspector development documentation · Configuration & state"},"headers":[],"relativePath":"en/reference/configuration.md","filePath":"en/reference/configuration.md"}'),o={name:"en/reference/configuration.md"};function s(r,e,c,d,l,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="configuration-state" tabindex="-1">Configuration &amp; state <a class="header-anchor" href="#configuration-state" aria-label="Permalink to &quot;Configuration &amp; state&quot;">​</a></h1><h2 id="managed-home" tabindex="-1">Managed home <a class="header-anchor" href="#managed-home" aria-label="Permalink to &quot;Managed home&quot;">​</a></h2><p>Selection priority is <code>--home PATH</code>, then <code>MOBILE_INSPECTOR_HOME</code>, then OS-user storage. The chosen directory must be new/empty or tool-owned. Foreign, escaping, symlinked or insecure state is rejected; legacy state is not silently migrated. Persistent state holds TLS identity and trusted project metadata. Runtime capabilities, body grants and captures belong to the current run; captures remain memory-only.</p><p>Never paste capability values into commands, URLs, prompts or exports. Viewer cookies and SDK pairing tokens cannot authorize machine APIs. <code>instance status --json</code> checks the authenticated owner; a stale file alone does not authorize process termination.</p><h2 id="trusted-project-configuration" tabindex="-1">Trusted project configuration <a class="header-anchor" href="#trusted-project-configuration" aria-label="Permalink to &quot;Trusted project configuration&quot;">​</a></h2><p><code>project add --root PATH --name NAME</code> selects a trusted Git root. Build mappings require an existing commit and contained source root. If a registered root/commit becomes unavailable, the running owner&#39;s project list exposes availability diagnostics; remove deliberately or restore resources, then restart for validation. Do not edit the registry offline.</p><p>A minimal diagnosis policy is explicit and inert:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;schemaVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;automation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;off&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Save through <code>project diagnosis-config --project ID --file PATH</code> using a regular, non-symlink UTF-8 JSON file (16 KiB maximum). Saving does not open a lease or run a model. Unknown fields reject. Provider descriptors contain only selected HTTPS endpoint/model and environment-variable name, never a credential value. Actual operational diagnosis remains unavailable; see <a href="./diagnosis">the lifecycle reference</a>.</p>',9)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
